	/**
	 * Default Constructor
	 */
    public DimensionService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new DimensionEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DimensionRepository.class) );
		this.validator		= applicationContext.getBean(DimensionValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Dimension
	 */
		public Dimension createDimension( CreateDimensionCommand command ) {

		Dimension entity = new Dimension();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDimensionId( command.getDimensionId() );
            entity.setName( command.getName() );
            entity.setTypeTime( command.getTypeTime() );
            entity.setDimensionType( command.getDimensionType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Dimension {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateDimensionCommand
	 * @return		Dimension
	 */
	public Dimension updateDimension( UpdateDimensionCommand command ) {

		Dimension entity = new Dimension();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setDimensionId( command.getDimensionId() );
            entity.setName( command.getName() );
            entity.setTypeTime( command.getTypeTime() );
            entity.setSemanticModel( command.getSemanticModel() );
            entity.setDatasets( command.getDatasets() );
            entity.setGlossaryTerms( command.getGlossaryTerms() );
            entity.setDimensionType( command.getDimensionType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Dimension {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteDimensionCommand
	 */
	public void delete( DeleteDimensionCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getDimensionId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Dimension {0} ", id );

	}

	/**
	 * Method to retrieve the Dimension via DimensionFetchOneSummary
	 * @param 	summary DimensionFetchOneSummary
	 * @return 	DimensionFetchOneResponse
	 */
	public Dimension getDimension( DimensionFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DimensionFetchOneSummary arg cannot be null" );

		Dimension entity = null;
		UUID id = summary.getDimensionId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Dimension using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Dimensions
	 *
	 * @return 	List<Dimension>
	 */
    public List<Dimension> getAllDimension() {
		List<Dimension> list = projector.findAll( new FindAllDimensionQuery() );
		return list;
	}

	/**
	 * assign SemanticModel on Dimension
	 * @param		command AssignSemanticModelToDimensionCommand
	 */
	public void assignSemanticModel( AssignSemanticModelToDimensionCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignSemanticModel(command.getDimensionId(), command.getAssignment());

	}

	/**
	 * unAssign SemanticModel on Dimension
	 * @param		command UnAssignSemanticModelFromDimensionCommand
	 */
	public void unAssignSemanticModel( UnAssignSemanticModelFromDimensionCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignSemanticModel(command.getDimensionId());
	}
	

